--
-- Name: assign_user_and_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_user_and_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Benutzer erstellen, wenn noch nicht existiert
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'user_' || NEW.user_id::text) THEN
        EXECUTE format('CREATE USER %I;', 'user_' || NEW.user_id::text);
    END IF;

    -- Basierend auf die Spalte 'role' die entsprechende Role zuweisen
    IF NEW.role = 'borrower' THEN
        EXECUTE format('GRANT borrower_role TO %I;', 'user_' || NEW.user_id::text);
    ELSIF NEW.role = 'worker' THEN
        EXECUTE format('GRANT worker_role TO %I;', 'user_' || NEW.user_id::text);
    ELSIF NEW.role = 'admin' THEN
        EXECUTE format('GRANT admin_role TO %I;', 'user_' || NEW.user_id::text);
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Fehler bei der Zuweisung der Rolle: %', SQLERRM;
        RETURN NULL;
END;
$$;


ALTER FUNCTION public.assign_user_and_role() OWNER TO postgres;

--
-- Name: set_due_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_due_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.DUE_DATE := NEW.CHECKOUT_DATE + INTERVAL '28 days';
RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Fehler beim Setzen des Fälligkeitsdatums: %', SQLERRM;
RETURN NEW; -- oder RETURN NULL, um das Einfügen zu verhindern
END;
$$;


ALTER FUNCTION public.set_due_date() OWNER TO postgres;

--
-- Name: set_return_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_return_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.STATUS = 'returned' AND OLD.STATUS = 'borrowed' THEN
        NEW.RETURN_DATE := CURRENT_DATE;
END IF;
RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Fehler beim Setzen des Rückgabedatums: %', SQLERRM;
RETURN NEW; -- oder RETURN NULL, um die Aktualisierung zu verhindern,
END;
$$;


ALTER FUNCTION public.set_return_date() OWNER TO postgres;

